+class DeleteConfirmDialog {
+  constructor() {
+    this.dialog = null;
+    this.overlay = null;
+    this.currentImageId = null;
+    this.init();
+  }
+
+  init() {
+    this.createDialog();
+    this.attachEventListeners();
+  }
+
+  createDialog() {
+    this.overlay = document.querySelector('.modal-overlay');
+    this.dialog = this.overlay.querySelector('.modal-content');
+  }
+
+  attachEventListeners() {
+    // Attach to all trigger buttons
+    document.querySelectorAll('.trigger').forEach((trigger) => {
+      trigger.addEventListener('click', (e) => {
+        e.preventDefault();
+        const imageCard = trigger.closest('.image-card');
+        const imageTitle = imageCard.querySelector('.image-title').textContent;
+        this.currentImageId = imageCard.dataset.id;
+        this.open(imageTitle);
+      });
+    });
+
+    // Close button
+    document.querySelector('.modal-close').addEventListener('click', () => {
+      this.close();
+    });
+
+    // Cancel button
+    document.querySelector('[data-action="cancel"]').addEventListener('click', () => {
+      this.close();
+    });
+
+    // Delete button
+    document.querySelector('[data-action="delete"]').addEventListener('click', () => {
+      this.handleDelete();
+    });
+
+    // Close on overlay click
+    this.overlay.addEventListener('click', (e) => {
+      if (e.target === this.overlay) {
+        this.close();
+      }
+    });
+
+    // Close on Escape key
+    document.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape' && this.overlay.classList.contains('open')) {
+        this.close();
+      }
+    });
+  }
+
+  open(imageTitle) {
+    const fileNameElement = this.dialog.querySelector('[data-image-name]');
+    if (fileNameElement) {
+      fileNameElement.textContent = imageTitle;
+    }
+    this.overlay.classList.add('open');
+  }
+
+  close() {
+    this.overlay.classList.remove('open');
+    this.currentImageId = null;
+  }
+
+  handleDelete() {
+    if (this.currentImageId) {
+      const imageCard = document.querySelector(`[data-id="${this.currentImageId}"]`);
+      if (imageCard) {
+        // Add fade-out animation
+        imageCard.style.opacity = '0';
+        imageCard.style.transform = 'scale(0.95)';
+        setTimeout(() => {
+          imageCard.remove();
+        }, 300);
+      }
+    }
+    this.close();
+  }
+}
+
+// Initialize on DOM load
+document.addEventListener('DOMContentLoaded', () => {
+  new DeleteConfirmDialog();
+});
+
')

